def run_prompt_tests(cases, call_llm) -> dict:
    passed = 0
    failed = []
    for case in cases:
        answer = call_llm(case['input']).lower()
        if all(s.lower() in answer for s in case['must_contain']):
            passed += 1
        else:
            failed.append(case['input'])
    total = len(cases)
    return {
        'passed': passed,
        'failed': failed,
        'pass_rate': passed / total if total else 0.0,
    }
